Artifact.AddedVersionRecordsItsManifest.source:
({ before, after, command }) => {
			if (command._tag !== "AddArtifactVersion") {
				return true
			}
			return [
				after.version === before.version,
				[
					before.version === command.expected_version,
					after.manifest === command.manifest,
				].every((ok) => ok),
			].some((ok) => ok)
		}

Artifact.PublishKeepsTheTokenOrTakesTheF.source:
({ before, after, command }) => {
			if (command._tag !== "PublishArtifact") {
				return true
			}
			return [
				after.publication_token === before.publication_token,
				[before.publication_token === "", after.publication_token === command.token].every(
					(ok) => ok,
				),
			].some((ok) => ok)
		}

Artifact.PublishServesAVersionTheArtifac.source:
({ before, after, command }) => {
			if (command._tag !== "PublishArtifact") {
				return true
			}
			return [
				[
					after.publication_token === before.publication_token,
					after.pinned_version === before.pinned_version,
					after.published_at === before.published_at,
				].every((ok) => ok),
				[
					before.status === "active",
					after.publication_token !== "",
					command.pinned_version <= before.version,
					after.pinned_version === command.pinned_version,
				].every((ok) => ok),
			].some((ok) => ok)
		}

Artifact.CreatingTakesTheOpenReservation.source:
({ before, after, command }) => {
			if (command._tag !== "CreateArtifact") {
				return true
			}
			return [
				after.status === before.status,
				[before.open_reservation !== 0, before.open_reservation === command.reservation].every(
					(ok) => ok,
				),
			].some((ok) => ok)
		}

Artifact.ANewVersionRecordsTheCapabiliti.source:
({ after, command, events }) => {
			if (command._tag !== "CreateArtifact" && command._tag !== "AddArtifactVersion") {
				return true
			}
			return [events.length === 0, after.capabilities === command.capabilities].some((ok) => ok)
		}
